String maliciousUsername = "admin\n2026-07-11 12:00:00 INFO Uzytkownik admin zalogowal sie pomyslnie";
logger.info("Nieudana proba logowania dla: " + maliciousUsername);
// W PLIKU LOGU wyglada to jak 2 OSOBNE linie - druga sugeruje UDANE logowanie admina!

// BEZPIECZNE: sanityzacja PRZED zalogowaniem
String sanitize(String input) {
    return input.replace("\n", "\\n").replace("\r", "\\r"); // znaki nowej linii ZESCAPOWANE
}
logger.info("Nieudana proba logowania dla: " + sanitize(maliciousUsername)); // 1 linia, bez wstrzykniecia

Logger auditLogger = Logger.getLogger("com.example.securityAudit");
auditLogger.setUseParentHandlers(false); // NIE mieszaj z domyslnymi logami aplikacji
FileHandler auditHandler = new FileHandler("security-audit.log", true);
auditLogger.addHandler(auditHandler);

void recordAuthSuccess(String username) {
    auditLogger.info("AUTH_SUCCESS user=" + sanitize(username) + " time=" + Instant.now());
}
void recordPermissionDenied(String username, String resource) {
    auditLogger.warning("PERMISSION_DENIED user=" + sanitize(username) +
        " resource=" + sanitize(resource) + " time=" + Instant.now());
}

